const PE_coil=(x1,x2,y,col=PE_INK,w=3)=>{const n=4,r=(x2-x1)/(2*n);let d=`M${x1} ${y}`;for(let i=0;i<n;i++)d+=`A${r} ${r} 0 0 1 ${x1+2*r*(i+1)} ${y}`;return `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`};
